    private void BuildAdvanced()
    {
        foreach(Control child in advanced.Controls.Cast<Control>().ToArray())child.Dispose();advanced.Controls.Clear();if(Game==null)return;var kind=GamePerformanceController.Backend(Game);bool editable=kind==PerformanceBackend.Unreal&&configPath!=null;
        if(kind==PerformanceBackend.Cyberpunk){
            advanced.Controls.Add(new SmoothLabel{Text="Cyberpunk 2077 · параметры из файла игры",Width=600,Height=34,Font=new Font("Segoe UI",11,FontStyle.Bold)});
            if(configPath==null){advanced.Controls.Add(new SmoothLabel{Text="Запусти игру один раз или подключи её UserSettings.json кнопкой «Выбрать конфиг».",Width=600,Height=80});return;}
            try{foreach(var setting in CyberpunkGraphics.Describe(CyberpunkGraphics.Read(configPath))){Control editor;if(setting.Choices.Length>0){var picker=Picker();picker.Items.AddRange(setting.Choices.Select(v=>new NativeChoice(v)).ToArray());picker.SelectedIndex=Array.IndexOf(setting.Choices,nativeOptions.TryGetValue(setting.Key,out var saved)?saved:setting.Value);picker.SelectedIndexChanged+=(s,e)=>{if(picker.SelectedItem is NativeChoice choice){nativeOptions[setting.Key]=choice.Value;Edited();}};editor=picker;}else{var number=Number(0,1000,0);number.DecimalPlaces=setting.Type=="float"?2:0;number.Minimum=(decimal)Math.Clamp(setting.Minimum??0,-100000,100000);number.Maximum=(decimal)Math.Min(100000,setting.Maximum??1000);string initial=nativeOptions.TryGetValue(setting.Key,out var saved)?saved:setting.Value;if(decimal.TryParse(initial,NumberStyles.Float,CultureInfo.InvariantCulture,out decimal value))number.Value=Math.Clamp(value,number.Minimum,number.Maximum);number.ValueChanged+=(s,e)=>{nativeOptions[setting.Key]=number.Value.ToString(CultureInfo.InvariantCulture);Edited();};editor=number;}
                    var row=Setting(GraphicsNames.Translate(setting.Name),editor);row.Width=620;row.Height=54;advanced.Controls.Add(row);
                }}catch(Exception ex)when(ex is IOException or InvalidDataException or Newtonsoft.Json.JsonException){advanced.Controls.Add(new SmoothLabel{Text="Не удалось прочитать конфигурацию: "+ex.Message,Width=600,Height=90});}
        }else{
            advanced.Controls.Add(new SmoothLabel{Text=editable?"Unreal Engine · отдельные параметры качества":"Отдельные параметры доступны для Unreal с подключённым GameUserSettings.ini. Для этой игры доступные функции указаны на вкладке «Экран».",Width=600,Height=editable?36:90});
            if(kind!=PerformanceBackend.Unreal){UiLayout.Apply(advanced);return;}
            foreach(var parameter in GraphicsParameters.Unreal){var picker=Picker();picker.Items.AddRange(new object[]{"Низкое","Среднее","Высокое","Максимальное"});picker.SelectedIndex=detailLevels.TryGetValue(parameter.Key,out int current)?current:quality.SelectedIndex<0?1:quality.SelectedIndex;picker.Enabled=editable;picker.SelectedIndexChanged+=(s,e)=>{detailLevels[parameter.Key]=picker.SelectedIndex;Edited();};var row=Setting(parameter.Name,picker);row.Width=620;row.Height=54;advanced.Controls.Add(row);}
        }
        PresentationOptions.Apply(advanced);UiLayout.Apply(advanced);
    }
    private void UpdateBenchmark(){if(Game!=null&&snapshot!=null)benchmarkBrowser.SetContext(Game,snapshot);}
    private void UpdatePreview()
    {
        if(Game==null)return;try{
            if(GamePerformanceController.Backend(Game)==PerformanceBackend.Cyberpunk&&configPath!=null){var existing=CyberpunkGraphics.Describe(CyberpunkGraphics.Read(configPath)).ToDictionary(p=>p.Key);preview.Text="ТЕКУЩЕЕ → ВЫБРАННОЕ\n\n"+(nativeOptions.Count==0?"Отдельные изменения ещё не выбраны.":string.Join("\n\n",nativeOptions.Select(pair=>GraphicsNames.Translate(existing.TryGetValue(pair.Key,out var setting)?setting.Name:pair.Key)+": "+(setting==null?"параметр исчез из конфига":GraphicsNames.Value(setting.Value))+" → "+GraphicsNames.Value(pair.Value))));}
            else if(GamePerformanceController.Backend(Game)==PerformanceBackend.Unreal&&configPath!=null){var existing=GamePerformanceController.ReadConfig(configPath);var selected=CurrentProfile();int level=quality.SelectedIndex<0?1:quality.SelectedIndex;preview.Text="ТЕКУЩЕЕ → ВЫБРАННОЕ\n\n"+string.Join("\n\n",GraphicsParameters.Unreal.Select(p=>p.Name+": "+(existing.DetailLevels.TryGetValue(p.Key,out int old)?old.ToString():"не задано")+" → "+(selected.DetailLevels.TryGetValue(p.Key,out int value)?value:level)))+$"\n\nМасштаб: {existing.RenderScale}% → {selected.RenderScale}%\nЛимит: "+(selected.UnlimitedFps?"выключен":selected.TargetFps+" FPS");}
            else preview.Text="При запуске будут переданы поддерживаемые параметры:\n\n"+string.Join(" ",GamePerformanceController.BuildArguments(Game,CurrentProfile(),new(snapshot?.Width??1920,snapshot?.Height??1080)))+"\n\nОтдельного адаптера редактирования графического файла для этой игры пока нет.";
            preview.Text+="\n\nФайлы не меняются при просмотре. «Сохранить» сохраняет профиль; перед запуском применяются доступные параметры и создаётся исходная резервная копия. Откат доступен кнопкой «Откат».";
        }catch(Exception ex)when(ex is IOException or InvalidDataException or Newtonsoft.Json.JsonException or InvalidOperationException){preview.Text="Не удалось составить план: "+ex.Message;}
    }
