internal static class GraphicsNames
{
    internal static string Translate(string name)=>name switch{"TextureQuality"=>"Текстуры","FilmGrain"=>"Зернистость плёнки","ChromaticAberration"=>"Хроматическая аберрация","DepthOfField"=>"Глубина резкости","LensFlares"=>"Блики","MotionBlur"=>"Размытие движения","FieldOfView"=>"Угол обзора","MaximumFPS_Value"=>"Лимит FPS","MaximumFPS_OnOff"=>"Включить лимит FPS","DLSSFrameGen"=>"DLSS · генерация кадров","DLSS_D"=>"DLSS · реконструкция лучей","DLSS"=>"DLSS · масштабирование","RayTracing"=>"Трассировка лучей","ContactShadows"=>"Контактные тени","Anisotropy"=>"Анизотропная фильтрация","ShadowMeshQuality"=>"Геометрия теней","LocalShadowsQuality"=>"Локальные тени","CascadedShadowsRange"=>"Дальность каскадных теней","CascadedShadowsResolution"=>"Каскадные тени","DistantShadowsResolution"=>"Дальние тени","VolumetricFogResolution"=>"Объёмный туман","VolumetricCloudsQuality"=>"Объёмные облака","ScreenSpaceReflectionsQuality"=>"Экранные отражения","AmbientOcclusion"=>"Фоновое затенение","MirrorQuality"=>"Зеркала","LODPreset"=>"Детализация объектов","CrowdDensity"=>"Плотность толпы",_=>System.Text.RegularExpressions.Regex.Replace(name,"([a-z])([A-Z])","$1 $2")};
    internal static string Value(string value)=>value switch{"true"=>"Включено","false"=>"Выключено","Off"=>"Выключено","Low"=>"Низкое","Medium"=>"Среднее","High"=>"Высокое","Ultra"=>"Ультра","Quality"=>"Качество","Balanced"=>"Баланс","Performance"=>"Скорость","Ultra Performance"=>"Максимальная скорость",_=>value};
}

internal sealed record NativeChoice(string Value){public override string ToString()=>GraphicsNames.Value(Value);}
